"""learning_io: managed writes and source discovery for the learning store (continuous-learning-v2, Neva).

Every file the learning engine writes lives under one allowed root: the state root (event log,
analyzer lock) or the observations root (temp batches, archives). A symlink inside that root
would redirect those writes to a file the owner never meant to hand over, so every managed
write goes through here. The configured root is trusted input and used as its realpath, so a
root under a symlinked parent (a dotfile-managed ~/.local, /home linked to /var/home, macOS
/tmp and /var) works. Every component below it, the leaf included, must be a real directory or
file, and leaves are opened with O_NOFOLLOW.

Stdlib only. Imported by instinct-cli.py, instinct-analyze.py and neva_hooks/learning_trigger.py.
"""
import errno
import os
import stat
import tempfile
from pathlib import Path

_NOFOLLOW = getattr(os, "O_NOFOLLOW", 0)


class ManagedPathError(Exception):
    """A managed write was refused because its path leaves the allowed root."""


def _symlink_error(link: Path, root: Path) -> ManagedPathError:
    try:
        target = os.readlink(link)
    except OSError:
        target = "?"
    return ManagedPathError(
        f"refusing to write through {link}: it is a symlink (to {target}). "
        f"Fix: replace {link} with a real file or directory inside {root}, "
        f"or point the Neva path setting at the real location.")


def check(root, path) -> Path:
    """Return the real path of `path`, which must sit under `root`. The root is trusted after
    realpath; a symlink in any component below it is refused."""
    # expanduser only: callers read and write the literal path, so expanding $NAME here would
    # move a write to where no reader looks.
    root, path = (Path(os.path.expanduser(os.fspath(p))) for p in (root, path))
    root = root if root.is_absolute() else Path.cwd() / root
    path = path if path.is_absolute() else Path.cwd() / path
    if ".." in root.parts or ".." in path.parts:
        raise ManagedPathError(f"refusing to write {path}: '..' leaves {root}. Fix: use a plain path.")
    real_root = Path(os.path.realpath(root))
    # `path` may be spelled from the configured root or from its realpath (ensure_dir and
    # check return real paths that callers then extend).
    for base in (root, real_root):
        try:
            rel = path.relative_to(base)
            break
        except ValueError:
            continue
    else:
        raise ManagedPathError(f"refusing to write {path}: it is outside {root}. "
                               f"Fix: keep learning data under {root}.")
    cur = real_root
    for part in rel.parts:
        cur = cur / part
        if cur.is_symlink():
            raise _symlink_error(cur, root)
    return cur


def ensure_dir(root, path) -> Path:
    """Create `path` and its root, refusing symlinks in every path component."""
    root, path = check(root, root), check(root, path)
    root.mkdir(parents=True, exist_ok=True)
    cur = root
    for part in path.relative_to(root).parts:
        cur = cur / part
        try:
            os.mkdir(cur, 0o700)
        except FileExistsError:
            pass
        st = os.lstat(cur)
        if stat.S_ISLNK(st.st_mode):
            raise _symlink_error(cur, root)
        if not stat.S_ISDIR(st.st_mode):
            raise ManagedPathError(f"refusing to write under {cur}: it is not a directory. "
                                   f"Fix: move that file out of {root}.")
    return path


def observation_sources(obs_dir) -> list:
    """The files the analyzer reads for one project bucket, oldest first: those the observe hook
    rotated into observations.pending/ (by name, which starts with the rotation time), then the
    live observations.jsonl. Hidden files are a run's in-flight state, never a source; the
    analyzer recovers any an interrupted run left behind before it discovers. The same-day
    trigger counts exactly these, so it fires only on data the analyzer will actually read."""
    obs_dir = Path(obs_dir)
    pending_dir = obs_dir / "observations.pending"
    sources = sorted(p for p in pending_dir.glob("*.jsonl") if not p.name.startswith(".")) \
        if pending_dir.is_dir() else []
    live = obs_dir / "observations.jsonl"
    if live.exists() or live.is_symlink():
        sources.append(live)
    return sources


def _open_leaf(root, path, flags: int, mode: int = 0o600) -> int:
    root, path = check(root, root), check(root, path)
    ensure_dir(root, path.parent)
    check(root, path)
    try:
        return os.open(path, flags | _NOFOLLOW, mode)
    except OSError as exc:
        if exc.errno in (errno.ELOOP, errno.EMLINK) or path.is_symlink():
            raise _symlink_error(path, root) from None
        raise


def open_append(root, path, binary: bool = False):
    """Append-only handle on a managed file, created 0600 if missing."""
    fd = _open_leaf(root, path, os.O_WRONLY | os.O_APPEND | os.O_CREAT)
    return os.fdopen(fd, "ab") if binary else os.fdopen(fd, "a", encoding="utf-8")


def open_lock(root, path):
    """Read-write handle for flock: created if missing, never truncated."""
    return os.fdopen(_open_leaf(root, path, os.O_RDWR | os.O_CREAT), "r+")


def write_new(root, path, data: bytes) -> None:
    """Write a file that must not exist yet (O_EXCL), so nothing existing is ever replaced."""
    fd = _open_leaf(root, path, os.O_WRONLY | os.O_CREAT | os.O_EXCL)
    with os.fdopen(fd, "wb") as fh:
        fh.write(data)


def write_text_atomic(root, path, content: str) -> None:
    """Replace a managed text file, checking destination and temporary file paths."""
    path = check(root, path)
    ensure_dir(root, path.parent)
    fd, name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(content)
            fh.flush()
            os.fsync(fh.fileno())
        check(root, temporary)
        check(root, path)
        os.replace(temporary, path)
    finally:
        check(root, temporary)
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


class LearningDataError(Exception):
    """A learning JSON file needs repair before processing can continue."""

def read_json_object(path):
    """Only an absent file is empty. Invalid JSON or a non-object is an error."""
    import json
    path = Path(path)
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return {}
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LearningDataError(f"{path}: cannot read a JSON object: {exc}. "
                                "Fix: repair this file before retrying; nothing was replaced.") from None
    if not isinstance(data, dict):
        raise LearningDataError(f"{path}: expected a JSON object. "
                                "Fix: repair this file before retrying; nothing was replaced.")
    return data


def load_analyzer_config(config_file) -> dict:
    """Validate file and environment settings identically for analysis and its trigger."""
    defaults = {"min_observations_to_analyze": 20, "max_analysis_lines": 500, "model": "haiku",
                "timeout_seconds": 120, "max_turns": 0, "max_batches_per_run": 4}
    data = read_json_object(config_file).get("analyze", {})
    if not isinstance(data, dict):
        raise LearningDataError(
            f"{config_file}: analyze must be a JSON object. Fix: repair analyze before retrying.")
    def validate(key, value, location):
        minimum = 0 if key == "max_turns" else 1
        valid = (isinstance(value, str) and bool(value.strip())) if key == "model" else (
            type(value) is int and value >= minimum)
        if not valid:
            required = "a nonempty string" if key == "model" else f"an integer >= {minimum}"
            raise LearningDataError(
                f"{location} must be {required}. Fix: repair {location} before retrying; "
                "nothing was written.")

    for key in defaults:
        if key in data:
            validate(key, data[key], f"{config_file}: analyze.{key}")
    defaults.update({k: v for k, v in data.items() if k in defaults})
    env_map = {"NEVA_INSTINCT_MIN_OBSERVATIONS": ("min_observations_to_analyze", int),
               "NEVA_INSTINCT_MAX_ANALYSIS_LINES": ("max_analysis_lines", int),
               "NEVA_INSTINCT_MODEL": ("model", str),
               "NEVA_INSTINCT_TIMEOUT_SECONDS": ("timeout_seconds", int),
               "NEVA_INSTINCT_MAX_TURNS": ("max_turns", int),
               "NEVA_INSTINCT_MAX_BATCHES": ("max_batches_per_run", int)}
    for env, (key, cast) in env_map.items():
        if env in os.environ:
            try:
                value = cast(os.environ[env])
            except ValueError:
                raise LearningDataError(
                    f"{env} must be an integer. Fix: repair or unset {env} before retrying; "
                    "nothing was written.") from None
            validate(key, value, env)
            defaults[key] = value
    return defaults
